// Extract date from input or use today
const input = $json.body.input || {};
const rawDate = input.date || null;

let dateStr;
if (rawDate) {
  // Try to parse the provided date
  const parsed = new Date(rawDate);
  dateStr = isNaN(parsed.getTime())
    ? rawDate
    : parsed.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
} else {
  dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
}

// Sample daily tasks
const tasks = [
  { id: 1, title: 'Check order status', completed: false, priority: 'high' },
  { id: 2, title: 'Review new signups', completed: false, priority: 'medium' },
  { id: 3, title: 'Process pending deliveries', completed: false, priority: 'high' },
  { id: 4, title: 'Update inventory', completed: true, priority: 'low' }
];

const pending = tasks.filter(t => !t.completed);
const completed = tasks.filter(t => t.completed);

// Build markdown
const taskLines = tasks.map(t => {
  const checkbox = t.completed ? '[x]' : '[ ]';
  const priorityBadge = t.priority === 'high' ? ' :red_circle:' : t.priority === 'medium' ? ' :yellow_circle:' : '';
  return `- ${checkbox} ${t.title}${priorityBadge}`;
}).join('\n');

const markdownContent = [
  `## Daily Check - ${dateStr}`,
  '',
  taskLines,
  '',
  `**Summary:** ${pending.length} pending task${pending.length !== 1 ? 's' : ''}, ${completed.length} completed.`
].join('\n');

return [{
  json: {
    markdown_content: markdownContent,
    tasks: tasks,
    status: 'ok'
  }
}];
